mapper.select:
SELECT s.*, wc.`name` AS customer_name, wu.user_name AS inviter_name FROM we_live_statistic s LEFT JOIN we_customer wc ON wc.external_userid = s.external_userid AND wc.corp_id = s.corp_id LEFT JOIN we_user wu ON wu.user_id = s.inviter_userid AND wu.corp_id = s.corp_id INNER JOIN we_flower_customer_rel wfcr ON wfcr.external_userid = s.external_userid AND wfcr.corp_id = s.corp_id AND wfcr.status = '0'
s.corp_id = #{corpId}
AND s.livingid = #{livingid}
AND EXISTS (SELECT 1 FROM we_live_item i WHERE i.id = s.item_id AND i.room_id = #{roomId} AND i.del_flag = 0)
AND wfcr.user_id IN
#{userId}
AND s.create_time >= #{beginTime}
AND s.create_time <= #{endTime}
GROUP BY s.id ORDER BY s.enter_time DESC

SELECT s.*, wc.`name` AS customer_name, wu.user_name AS inviter_name FROM we_live_statistic s LEFT JOIN we_customer wc ON wc.external_userid = s.external_userid AND wc.corp_id = s.corp_id LEFT JOIN we_user wu ON wu.user_id = s.inviter_userid AND wu.corp_id = s.corp_id INNER JOIN we_flower_customer_rel wfcr ON wfcr.external_userid = s.external_userid AND wfcr.corp_id = s.corp_id AND wfcr.status = '0'
s.corp_id = #{corpId}
AND s.livingid = #{livingid}
AND EXISTS (SELECT 1 FROM we_live_item i WHERE i.id = s.item_id AND i.room_id = #{roomId} AND i.del_flag = 0)
AND wfcr.user_id IN ( SELECT wu2.user_id FROM we_user wu2 WHERE wu2.corp_id = #{corpId} AND wu2.del_flag = 0 AND FIND_IN_SET(wu2.department, #{departmentDataScope}) )
AND s.create_time >= #{beginTime}
AND s.create_time <= #{endTime}
GROUP BY s.id ORDER BY s.enter_time DESC
